# Hutulmare (Carpathia No. 10128) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py); the game has no sculptor for it, so its export is a body generated by rule and only its bones,
# clips and size are kept:
#   blender --background --factory-startup --python sculpts/hutulmare.py -- <the export's Hutulmare.glb> <out.glb>
#
# Grown from hutulet.py (its palette, locks, hooves, drape, eyes and face, through sibling("hutulet")). From the
# picture (10128-Hutulmare.jpg) and the brief (CP-dex-3, "128. Hutulmare"): a strong, compact mountain horse in bay
# brown (the brief says dun; the picture's bay is kept, the foal's own colour) with a deep barrel; a long head
# carried forward with a dark grey muzzle; a long black mane falling down both sides of the neck and a forelock over
# the brow; brown ears; kind dark eyes; a dark stripe down the spine; dark zebra bars on the legs; black feathered
# fetlocks over dark grey hooves; a long black tail hanging nearly to the ground; a folk saddle blanket in red and
# black with white zigzag borders and a fringe of cream and black tassels; a breast collar of the same weave with
# tassels; a wooden saddle with its horn; two wooden saddlebag crates with iron buckles, and a third on the rump.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import (Kit, ell, tube, lathe, sheet, hull, slab, ring_band, lumpy, srgb, inside, unit, outward,
                       args, sibling)

hl = sibling("hutulet")
BAY, BAY_DARK, BAY_PALE, MANE, SOCK = hl.BAY, hl.BAY_DARK, hl.BAY_PALE, hl.MANE, hl.SOCK
RED, CREAM, BLACK, MUZZLE = hl.RED, hl.CREAM, hl.BLACK, hl.MUZZLE
WOOD, WOOD_DARK, STRAP, IRON = "#8C5E34", "#5A3A1E", "#3E2416", "#7E8288"


def box(c, half, color, k, name, bone="body"):
    """A wooden crate: a box with hard edges, its planks drawn as darker slats standing proud on its outer face."""
    c, (hx, hy, hz) = np.array(c, float), half
    P = [c + (sx * hx, sy * hy, sz * hz) for sx in (-1, 1) for sy in (-1, 1) for sz in (-1, 1)]
    k.add(name, hull(P), color, bone, fuse=False, surface="leather")


def hutulmare(src, out):
    k = Kit(src, coat="fur")

    # --- the trunk: a deep barrel, the belly at 0.3 of the height, broad chest and rump ------------------------
    Z = 0.548
    k.add("barrel", ell((0, 0.01, Z), (0.165, 0.25, 0.215)), BAY, "body")
    k.add("chest", ell((0, -0.17, Z + 0.02), (0.158, 0.15, 0.205), deform=lumpy(7, 4, 0.025)), BAY, "body")
    k.add("rump", ell((0, 0.19, Z + 0.01), (0.16, 0.15, 0.2)), BAY, "body")
    # shoulders and haunches fused over the legs' upper half
    k.add("shoulder", ell((0.11, -0.165, 0.42), (0.072, 0.092, 0.16)), BAY, "leg{s}", mirror=True)
    k.add("thigh", ell((0.112, 0.175, 0.44), (0.078, 0.105, 0.17)), BAY, "hind{s}", mirror=True)
    for nm, y, bone in (("fore", -0.165, "leg{s}"), ("hind", 0.175, "hind{s}")):
        k.add(nm, tube([(0.112, y, 0.42), (0.112, y - 0.004, 0.24), (0.112, y - 0.01, 0.08)], [0.062, 0.052, 0.049]),
              BAY, bone, mirror=True)
        k.add(nm + "cuff", ell((0.112, y - 0.014, 0.1), (0.068, 0.07, 0.06), deform=lumpy(6, 2, 0.14)), SOCK,
              bone, mirror=True)
        hl.hoof(k, 0.112, y - 0.016, 0.062, 0.066, bone)
        # the zebra bars: three dark rings round the lower leg
        for j, z in enumerate((0.19, 0.25, 0.31)):
            r = 0.0505 + 0.0045 * (z - 0.19) / 0.12
            k.add(f"{nm}bar{j}", ring_band((0.112, y - 0.006, z), (0, 0.3, 1), r - 0.002, 0.03, thick=0.005),
                  BAY_DARK, bone, fuse=False, mirror=True, surface="fur")

    # --- the neck and the long head carried forward, its face sloping down to the dark muzzle -------------------
    k.add("neck", tube([(0, -0.2, 0.62), (0, -0.28, 0.78), (0, -0.33, 0.88)], [0.125, 0.105, 0.094]), BAY, "head")
    H, HR = np.array([0, -0.375, 0.9]), np.array([0.108, 0.112, 0.108])
    k.add("head", ell(H, HR), BAY, "head")
    k.add("face", ell((0, -0.465, 0.8), (0.088, 0.135, 0.085), rot=(40, 0, 0)), BAY, "head")
    MZ, MR = np.array([0, -0.535, 0.725]), np.array([0.084, 0.084, 0.078])
    k.add("muzzle", ell(MZ, MR), MUZZLE, "head", surface="skin")
    k.add("jowl", ell((0, -0.36, 0.8), (0.1, 0.09, 0.09)), BAY, "head")
    hl.face(k, MZ, MR, 1.25, smile=False)
    # ears standing up out of the mane
    EB, ET = np.array([0.058, -0.36, 0.99]), np.array([0.076, -0.375, 1.075])
    k.add("ear", tube([EB, (EB + ET) / 2 + (0.006, -0.008, 0), ET], [0.034, 0.033, 0.011]), BAY, "ear{s}",
          mirror=True)
    k.decal((EB + ET) / 2 + (0.004, -0.028, -0.006), unit(0.2, -1, 0.1), (0.015, 0.028), hl.EAR_IN,
            up=unit(0.3, 0, 1), eps=0.003, rings=8, segs=40, mirror=True)

    # --- the mane: a forelock to the eyes, long locks down both sides of the neck, their tips lifting out -------
    hair = []
    for x, zt in ((-0.035, 0.85), (-0.01, 0.83), (0.016, 0.855), (0.042, 0.84)):
        a = np.array([x, -0.37, 1.0])
        hair.append(([a, (x * 1.1, -0.445, 0.985), (x * 1.2, -0.48, 0.93), (x * 1.25, -0.49, zt)], 0.042,
                     unit(0, -1, 0.35)))
    for sx in (1, -1):
        a = np.array([0.06 * sx, -0.34, 1.0])
        hair.append(([a, (0.11 * sx, -0.33, 0.98), (0.15 * sx, -0.32, 0.9), (0.17 * sx, -0.31, 0.82)], 0.04,
                     unit(0.7 * sx, 0, 0.7)))
    for i, (t, L) in enumerate(zip(np.linspace(0, 1, 6), (0.32, 0.3, 0.33, 0.29, 0.26, 0.2))):
        a = np.array([0, -0.32, 0.99]) * (1 - t) + np.array([0, -0.12, 0.8]) * t
        for sx in (1, -1):
            L2 = L * (0.88 if (i + (sx > 0)) % 2 else 1.05)
            d = unit(0.5 * sx, 0.18 + 0.08 * (i % 2), -0.85)
            hair.append(([a, a + d * L2 * 0.35 + (0.02 * sx, 0, 0.02), a + d * L2 * 0.8 + (0.015 * sx, 0, 0),
                          a + d * L2 + (0.04 * sx, 0.01, 0.015)], 0.052, unit(0.85 * sx, 0, 0.5)))
    # more locks over the near (+X) side of the neck, as the picture hangs them, and the crest's own mass
    for i, t in enumerate(np.linspace(0.1, 0.8, 4)):
        a = np.array([0.02, -0.32, 0.99]) * (1 - t) + np.array([0.02, -0.12, 0.8]) * t
        d = unit(0.35, -0.05 + 0.1 * (i % 2), -0.93)
        L = 0.3 - 0.05 * t
        hair.append(([a, a + d * L * 0.35 + (0.05, 0, 0.0), a + d * L * 0.8 + (0.06, 0, 0),
                      a + d * L + (0.08, 0.01, 0.02)], 0.05, unit(0.95, 0, 0.3)))
    crest = [np.array(p, float) for p in ((0, -0.36, 1.005), (0, -0.28, 0.965), (0, -0.2, 0.89), (0, -0.11, 0.795))]
    k.add("manecore", hl.lock(crest, 0.066, 0.6), MANE, "head", fuse=False, surface="hair")
    for i, (pts, r, ax) in enumerate(hair):
        bone = "head" if pts[0][1] < -0.2 else "body"
        k.add(f"mane{i}", hl.lock([np.array(p, float) for p in pts], r, 0.2, ax, 0.55, floor=0.016), MANE, bone,
              fuse=False, surface="hair")

    # --- the tail: long and black, hanging nearly to the ground, its tips flicking out toward +X ---------------
    TB = np.array((0, 0.31, 0.7))
    k.add("tailroot", ell(TB, (0.06, 0.06, 0.06)), MANE, "tail")
    core = [TB + (0, -0.01, 0.02), TB + (0.01, 0.08, -0.07), TB + (0.03, 0.12, -0.25), TB + (0.06, 0.14, -0.46)]
    k.add("tailcore", hl.lock(core, 0.07, 0.5, floor=0.018), MANE, "tail", fuse=False, surface="hair")
    for i, (ox, oz, r) in enumerate([(0.055, 0.02, 0.048), (-0.05, 0.02, 0.046), (0.045, -0.04, 0.044),
                                     (-0.035, -0.04, 0.042), (0.075, -0.01, 0.04), (0.0, 0.06, 0.04)]):
        off = np.array([ox, 0, oz])
        pts = [core[0] + off * 0.2, core[1] + off * 0.6, core[2] + off, core[3] + off * 1.4 + (0.02, 0.02, 0.03)]
        k.add(f"tail{i}", hl.lock(pts, r, 0.3, floor=0.016), MANE, "tail", fuse=False, surface="hair")

    # --- the dark stripe down the spine, and a paler belly ----------------------------------------------------
    k.paint(lambda P: inside(np.abs(P[:, 0]) - 0.03, 0.004) * (P[:, 2] > 0.66) * (P[:, 1] > -0.26) * (P[:, 1] < 0.36),
            BAY_DARK, on=["barrel", "chest", "rump"])
    k.paint(lambda P: inside(P[:, 2] - 0.4, 0.03) * (P[:, 2] > 0.3) * (np.abs(P[:, 0]) < 0.09), BAY_PALE,
            on=["barrel", "chest", "rump"])

    # --- the saddle blanket: a black underlayer, the red cloth over it, white zigzag borders, tassels ----------
    cz = Z
    rad = lambda y: 0.228 + 0.0 * y
    under = hl.drape(cz, lambda y: rad(y) - 0.004, -0.15, 0.19, math.radians(98))
    k.add("blanketunder", outward(sheet(under, 45, 23, 0.01)), BLACK, "body", fuse=False, surface="cloth")
    cloth = hl.drape(cz, lambda y: rad(y) + 0.004, -0.12, 0.16, math.radians(90))
    k.add("blanket", outward(sheet(cloth, 41, 21, 0.01)), RED, "body", fuse=False, surface="cloth")
    lift = hl.drape(cz, lambda y: rad(y) + 0.007, -0.12, 0.16, math.radians(90))
    for i, (u0, w, amp) in enumerate([(0.07, 0.04, 0.0), (0.93, 0.04, 0.0), (0.17, 0.03, 0.03), (0.83, 0.03, 0.03)]):
        k.add(f"weave{i}", outward(sheet(hl.band(lift, u0, w, amp, 6), 7, 90, 0.016)), CREAM, "body", fuse=False,
              surface="cloth")
    for sx in (1, -1):
        for j, v in enumerate(np.linspace(0.04, 0.96, 9)):
            p = np.array(under(np.array(1.0 if sx > 0 else 0.0), np.array(v)), float) + (0.006 * sx, 0, 0.004)
            col = CREAM if j % 2 == 0 else BLACK
            k.add(f"tassel{'RL'[sx < 0]}{j}", hl.lock([p, p + (0.006 * sx, 0, -0.03), p + (0.01 * sx, 0, -0.055)],
                                                      0.014, 0.6, floor=0.012), col, "body", fuse=False,
                  surface="cloth")

    # --- the breast collar: a woven band round the chest's front, dipping in the middle, with tassels --------
    def collar_at(lift, w0, w1):
        def at(u, v):
            t = (2 * (0.015 + 0.97 * u) - 1) * math.radians(105)
            x = (0.172 + lift) * np.sin(t)
            y = -0.17 - (0.162 + lift) * np.cos(t)
            z = 0.68 - 0.08 * np.cos(t) ** 2 + w0 + (w1 - w0) * v
            return np.stack([x, y, z], axis=-1)
        return at
    k.add("collar", outward(sheet(collar_at(0.012, -0.028, 0.028), 61, 5, 0.012)), RED, "body", fuse=False,
          surface="cloth")
    k.add("collarband", outward(sheet(collar_at(0.016, -0.009, 0.009), 61, 3, 0.012)), CREAM, "body", fuse=False,
          surface="cloth")
    ca = collar_at(0.014, -0.028, 0.028)
    for j, u in enumerate(np.linspace(0.12, 0.88, 7)):
        p = np.array(ca(np.array(u), np.array(0.0)), float)
        col = BLACK if j % 2 else RED
        k.add(f"collartassel{j}", hl.lock([p, p + (0, -0.006, -0.03), p + (0, -0.008, -0.06)], 0.015, 0.55,
                                         floor=0.013), col, "body", fuse=False, surface="cloth")

    # --- the wooden saddle with its horn, and the crates ------------------------------------------------------
    top = cz + rad(0) + 0.012
    k.add("saddle", hull([(sx * 0.1, y, top + dz) for sx in (-1, 1) for y, dz in ((-0.1, 0.03), (0.06, 0.0))]
                         + [(sx * 0.13, y, top - 0.06) for sx in (-1, 1) for y in (-0.1, 0.06)]
                         + [(0, -0.12, top + 0.05), (0, 0.08, top + 0.03)]), WOOD_DARK, "body", fuse=False,
          surface="leather")
    k.add("horn", lathe((0, -0.12, top + 0.03), (0, -0.25, 1),
                        [(0, 0), (0.026, 0), (0.022, 0.05), (0.036, 0.07), (0.03, 0.09), (0, 0.095)]), WOOD,
          "body", fuse=False, surface="leather")
    for sx in (1, -1):
        cx = sx * 0.242
        box((cx, 0.03, 0.62), (0.055, 0.13, 0.095), WOOD, k, f"crate{'RL'[sx < 0]}")
        # dark slats across the outer face, a leather strap over it and two iron buckles
        for j, y in enumerate((-0.07, 0.0, 0.07)):
            box((cx + sx * 0.057, 0.03 + y, 0.62), (0.006, 0.006, 0.09), WOOD_DARK, k, f"slat{'RL'[sx < 0]}{j}")
        for j, y in enumerate((-0.05, 0.11)):
            box((cx + sx * 0.06, y, 0.635), (0.006, 0.016, 0.1), STRAP, k, f"strap{'RL'[sx < 0]}{j}")
            box((cx + sx * 0.068, y, 0.66), (0.006, 0.022, 0.02), IRON, k, f"buckle{'RL'[sx < 0]}{j}")
        box((sx * 0.19, 0.03, 0.75), (0.02, 0.1, 0.012), STRAP, k, f"hanger{'RL'[sx < 0]}")
    box((0, 0.16, top + 0.04), (0.11, 0.075, 0.05), WOOD, k, "cratetop")
    box((0, 0.16, top + 0.091), (0.112, 0.012, 0.004), STRAP, k, "cratetopstrap")

    # --- the eyes: kind and dark, high on the head's sides, a little forward ----------------------------------
    de = unit(0.64, -0.68, 0.34)
    E = hl.at_surface(H, HR, de)
    k.build(voxel=0.009, smooth=4, band=0.012)
    k.eye_states(hl.lay_eyes(k, E, de, (0.03, 0.034), BAY))
    k.export(out)


if __name__ == "__main__":
    hutulmare(*args())
